import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import path from 'node:path';
const [mode,dir]=process.argv.slice(2);assert(['single','concurrent','failure','cancel'].includes(mode));
const {raw,side,entry,stderr}=JSON.parse(readFileSync(path.join(dir,'result.json')));assert(['ts','rust'].includes(side));assert(entry&&Array.isArray(raw));assert(!raw.some(x=>x.probeError));
const calls=raw.map((x,i)=>({x,i})).filter(({x})=>x.kind==='request'&&x.module==='capability');const finals=raw.filter(x=>x.final);assert.equal(finals.length,1);
const model=raw.filter(x=>x.kind==='request'&&x.module==='model'&&x.payload?.operation==='stream');
if(mode==='single'){assert.equal(calls.length,1);assert.equal(calls[0].x.payload.toolCallId,'call1');assert.equal(model.length,2);assert.equal(finals[0].outcome,'completed');}
else {assert.deepEqual(calls.slice(0,2).map(({x})=>x.payload.toolCallId),['call1','call2']);const cancel=raw.findIndex(x=>x.probeSent?.method==='cancel');if(mode==='cancel'){assert.equal(calls.length,2);assert(cancel>calls[1].i);assert(raw.some(x=>x.inReplyTo==='cancel'&&x.ok===true));assert.equal(finals[0].outcome,'cancelled');}else{assert.equal(calls.length,3);assert.equal(calls[2].x.payload.toolCallId,'call3');const replies=raw.map((x,i)=>({x,i})).filter(({x})=>x.probeSent?.messageId?.startsWith('held-'));assert.deepEqual(replies.map(({x})=>x.probeSent.payload?.toolCallId??x.probeSent.messageId.slice(5)),['call2','call1']);assert(calls[1].i<replies[0].i&&replies[1].i<calls[2].i);const results=raw.filter(x=>x.payload?.type==='tool_result').map(x=>x.payload.result);assert.deepEqual(results.map(r=>r.toolCallId),['call1','call2','call3']);assert.deepEqual(results.map(r=>r.type),mode==='failure'?['error','success','success']:['success','success','success']);assert.equal(model.length,2);assert.equal(finals[0].outcome,'completed');}}
if(side==='rust')assert.equal(stderr,'');else assert(/^(?:\(node:[1-9][0-9]*\) ExperimentalWarning: SQLite is an experimental feature and might change at any time\n\(Use `node --trace-warnings \.\.\.` to show where the warning was created\)\n)?$/.test(stderr),'unexpected TS stderr');console.log(JSON.stringify({status:'PASS',mode,side}));
